import{_ as s,o,c as t,a4 as a}from"./chunks/framework.Dsbb2oA0.js";const h=JSON.parse('{"title":"部署与启动说明（MxServiceCode / MxCAD 转换程序）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/docs/9.AIManual/4.BackendReferenceDocs/3.DeploymentAndStartup.md","filePath":"zh/docs/9.AIManual/4.BackendReferenceDocs/3.DeploymentAndStartup.md"}'),i={name:"zh/docs/9.AIManual/4.BackendReferenceDocs/3.DeploymentAndStartup.md"};function n(d,e,c,l,p,r){return o(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="部署与启动说明-mxservicecode-mxcad-转换程序" tabindex="-1">部署与启动说明（MxServiceCode / MxCAD 转换程序） <a class="header-anchor" href="#部署与启动说明-mxservicecode-mxcad-转换程序" aria-label="Permalink to &quot;部署与启动说明（MxServiceCode / MxCAD 转换程序）&quot;">​</a></h1><blockquote><p>基于安装包实际目录与启动脚本整理。</p></blockquote><h2 id="一、程序位置-固定临时路径" tabindex="-1">一、程序位置（固定临时路径） <a class="header-anchor" href="#一、程序位置-固定临时路径" aria-label="Permalink to &quot;一、程序位置（固定临时路径）&quot;">​</a></h2><p>两类包：<strong>单独转换程序</strong>（MxConvert，仅含 mxcadassembly）与<strong>后端服务</strong>（MxServiceCode，同时含后端服务和转换程序，即完整超集）。下载地址以 <a href="./../1.EntryGuide.html">入口指引</a> 的&quot;链接清单&quot;为准（按需要 + 平台取对应行；Linux 包为 Ubuntu 20.04 x86_64 构建）。</p><p><strong>固定临时路径（只下载一次，跨会话复用；系统清理临时目录后重新下载即可）</strong>：</p><ul><li>Windows：<code>%TEMP%\\MxCAD\\</code>（<code>%TEMP%</code> 为用户 Temp 目录环境变量，命令中直接使用，无需手动展开）</li><li>Linux：<code>/tmp/MxCAD/</code></li></ul><p>按 <a href="./../1.EntryGuide.html">入口指引</a> 的排查步骤执行：先判断任务需要什么，再查看临时路径下有什么——什么都没有 → 按需要下载对应 zip（只需转换程序 → 单独 MxConvert 包；需要后端服务 → MxServiceCode 包，内含转换程序）解压到临时路径；只有转换程序 → 仅需转换程序时先做&quot;三、试用版有效期检测&quot;即可用，需要后端时清空重下后端包；已解包后端包 → 做过期检测 + 完整性验证，不完整清空重下。<strong>重新下载前必须先清空临时路径（各包目录结构固定，后端包是完整超集）。不要扫描用户机器其他目录。</strong></p><h3 id="解压后-windows-顶层只有一个目录-mxservicecode-tryversion-与-zip-同名" tabindex="-1">解压后（Windows：顶层只有一个目录 <code>MxServiceCode_TryVersion\\</code>，与 zip 同名） <a class="header-anchor" href="#解压后-windows-顶层只有一个目录-mxservicecode-tryversion-与-zip-同名" aria-label="Permalink to &quot;解压后（Windows：顶层只有一个目录 \`MxServiceCode_TryVersion\\\`，与 zip 同名）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MxServiceCode_TryVersion\\    ← 解压后的顶层目录（与 zip 同名）</span></span>
<span class="line"><span>├── MxServiceCode\\</span></span>
<span class="line"><span>│   ├── NODE.JS后台程序开发.doc   ← 官方后台开发教程（非 API 文档）</span></span>
<span class="line"><span>│   ├── MxServiceCode.sln        ← 解决方案文件</span></span>
<span class="line"><span>│   └── MxServiceCode\\           ← 工程目录（以下命令在此执行）</span></span>
<span class="line"><span>│       ├── bin\\node.exe          ← 内置 Node 运行时</span></span>
<span class="line"><span>│       ├── mxapp.js              ← 入口（命令行）</span></span>
<span class="line"><span>│       ├── src\\                  ← TS 源码（mxcad\\ 为 API 类，sample\\ 为示例，MxCommand.ts 为命令注册）</span></span>
<span class="line"><span>│       ├── Mx2DNode.node         ← 原生模块</span></span>
<span class="line"><span>│       ├── package.json          ← npm run build 编译</span></span>
<span class="line"><span>│       ├── test.bat              ← 测试脚本</span></span>
<span class="line"><span>│       ├── empty_template.dwg    ← 空白模板</span></span>
<span class="line"><span>│       ├── A3.dwg / BT.DWG       ← 图框 / 图签示例图块</span></span>
<span class="line"><span>│       └── t1.dwg / tree.dwg     ← 测试图纸</span></span>
<span class="line"><span>└── MxCAD\\</span></span>
<span class="line"><span>    └── Release\\                 ← 格式转换程序目录（mxcadassembly.exe + 运行依赖 dll + mxcad_ini.json、mxcode.bin、mxiconv.data + **fonts\\** + files\\）</span></span></code></pre></div><h3 id="解压后-linux-顶层只有一个目录-mxservicecode-tryversion-与-zip-同名" tabindex="-1">解压后（Linux：顶层只有一个目录 <code>MxServiceCode_TryVersion\\</code>，与 zip 同名） <a class="header-anchor" href="#解压后-linux-顶层只有一个目录-mxservicecode-tryversion-与-zip-同名" aria-label="Permalink to &quot;解压后（Linux：顶层只有一个目录 \`MxServiceCode_TryVersion\\\`，与 zip 同名）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>MxServiceCode_TryVersion\\    ← 解压后的顶层目录（与 zip 同名）</span></span>
<span class="line"><span>├── MxServiceCode\\</span></span>
<span class="line"><span>│   ├── NODE.JS后台程序开发.doc   ← 官方后台开发教程</span></span>
<span class="line"><span>│   └── MxServiceCode\\           ← 工程目录（无 .sln；内置运行时为 node 而非 bin\\node.exe，</span></span>
<span class="line"><span>│                                 另含 start_demo_MxServiceCode.sh、start_demo_systemlib_MxServiceCode.sh、Linux启动说明.txt）</span></span>
<span class="line"><span>└── Linux\\</span></span>
<span class="line"><span>    └── MxCAD\\                   ← 格式转换程序目录（mxcadassembly + 运行依赖 mx/so + mxcad_ini.json、mxcode.bin、mxiconv.data + **fonts\\** + files\\）</span></span></code></pre></div><blockquote><p><strong>转换程序目录</strong> = Windows 临时路径下 <code>MxServiceCode_TryVersion\\MxCAD\\Release\\</code>、Linux 临时路径下 <code>MxServiceCode_TryVersion\\Linux\\MxCAD\\</code>（单独 MxConvert 包则为 <code>MxConvert_TryVersion\\</code> 目录本身）；<strong>前端预览图纸所需字体 = 该目录下的 <code>fonts\\</code></strong>（复制它即可）。</p></blockquote><h2 id="二、运行-mxservicecode-命令-无需启动任何服务" tabindex="-1">二、运行 MxServiceCode 命令（无需启动任何服务） <a class="header-anchor" href="#二、运行-mxservicecode-命令-无需启动任何服务" aria-label="Permalink to &quot;二、运行 MxServiceCode 命令（无需启动任何服务）&quot;">​</a></h2><p>命令方式为独立进程，直接调用内置 node：</p><p><strong>Windows</strong>（工程目录下）：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bin\\node.exe mxapp.js getcaddata file=t1.dwg outfile=t1.dwg.json</span></span></code></pre></div><p><strong>Linux</strong>（工程目录下）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mxapp.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> getcaddata</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file=t1.dwg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> outfile=t1.dwg.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><p>无参数运行 <code>node mxapp.js</code> 可打印版本信息与日志路径。</p><blockquote><p>⚠️ <strong>内置 Node 版本限制（实测）</strong>：<code>bin\\node.exe</code> 为 <strong>v10.9.0</strong>，仅支持 <strong>CommonJS</strong>——ESM（<code>import</code> 语法 / <code>.mjs</code>）直接报 <code>SyntaxError</code>；也没有 <code>fetch</code>、可选链等新特性。用内置 node 写辅助脚本一律用 CommonJS（<code>require</code>）+ <code>.js</code>；需要 ESM 时改用系统 Node。</p></blockquote><h3 id="linux-首次部署-权限配置" tabindex="-1">Linux 首次部署（权限配置） <a class="header-anchor" href="#linux-首次部署-权限配置" aria-label="Permalink to &quot;Linux 首次部署（权限配置）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 777</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_demo_MxServiceCode.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start_demo_MxServiceCode.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 脚本内已完成 mxcadassembly、mx/so、Mx2DNode.node、node 的 chmod</span></span></code></pre></div><p>出错时改用 <code>./start_demo_systemlib_MxServiceCode.sh</code>（使用 systemLib 目录下的原生库）。</p><h2 id="三、格式转换程序-mxcadassembly-独立调用" tabindex="-1">三、格式转换程序 mxcadassembly（独立调用） <a class="header-anchor" href="#三、格式转换程序-mxcadassembly-独立调用" aria-label="Permalink to &quot;三、格式转换程序 mxcadassembly（独立调用）&quot;">​</a></h2><p><strong>Windows</strong>（转换程序目录下，两种形式等价，按 shell 选）：</p><ul><li>cmd / PowerShell（裸 JSON，即官方文档形式，无需编码）：</li></ul><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mxcadassembly.exe {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;srcpath&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.dwg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;outname&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;_trial.mxweb&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;outpath&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./out&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li>Git Bash（百分号编码串 + 引号；该 shell 下裸 JSON 会返回 <code>read file error</code>，实测）：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>mxcadassembly.exe &quot;[%7B%22srcpath%22%3A%221.dwg%22%2C%22outname%22%3A%22_trial.mxweb%22%2C%22outpath%22%3A%22.%2Fout%22%7D]&quot;</span></span></code></pre></div><p><strong>Linux</strong>（转换程序目录下，裸 JSON 加单引号即可）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 777</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mxcadassembly</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./mx/so/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./mxcadassembly</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;srcpath&quot;:&quot;1.dwg&quot;,&quot;outname&quot;:&quot;_trial.mxweb&quot;,&quot;outpath&quot;:&quot;./out&quot;}&#39;</span></span></code></pre></div><p>（等价备选形式：<code>./mxcadassembly &#39;[%7B%22srcpath%22%3A%221.dwg%22%2C%22outname%22%3A%22_trial.mxweb%22%2C%22outpath%22%3A%22.%2Fout%22%7D]&#39;</code>）</p><blockquote><p>参数形式约定：程序接受两种等价形式——① <strong>裸 JSON</strong>（官方文档形式，cmd / PowerShell / Linux bash 直接可用，bash 下用单引号包裹）；② <strong>百分号十六进制编码串 + 一层方括号</strong>（如 <code>{&quot;a&quot;:1}</code> → <code>[%7B%22a%22%3A1%7D]</code>，MxServiceCode 内部使用，Git Bash 必须用此形式）。MxServiceCode 内部的 <code>MxUtility.callMxCadAssembly</code> 已封装此逻辑，<strong>二开时优先通过 TS API 调用，不要手动拼命令</strong>。</p></blockquote><blockquote><p>⚠️ <strong>常见坑（实测）</strong></p><ul><li>编码必须带 <code>%</code> 前缀；误用纯十六进制（如 <code>7b2261223a317d</code>）会返回 <code>{&quot;code&quot;:1,&quot;message&quot;:&quot;read file error&quot;}</code></li><li><strong>cmd.exe / 批处理中 <code>%</code> 是批处理变量引用</strong>：百分号编码串会被展开破坏（返回 <code>{&quot;code&quot;:1,&quot;message&quot;:&quot;read file error&quot;}</code>），cmd 下必须用裸 JSON 形式</li><li>Windows 上 <code>python</code> 可能是 Store 占位程序（静默无输出）；生成编码参数的临时脚本用内置 <code>bin\\node.exe</code></li><li><code>convert</code> 命令不可用时（wgh 已废弃，见《MxServiceCode命令参考.md》详解 1），<strong>DWG→mxweb 以本独立调用为唯一途径</strong>；mxcad 前端只认 mxweb</li></ul></blockquote><h3 id="试用版有效期检测" tabindex="-1">试用版有效期检测 <a class="header-anchor" href="#试用版有效期检测" aria-label="Permalink to &quot;试用版有效期检测&quot;">​</a></h3><blockquote><p>转换程序为<strong>试用版，期限 6 个月</strong>。临时路径中已有转换程序，使用前必须先做<strong>测试转换</strong>（命令行方式，无需 GUI；在转换程序目录执行，用包内自带测试图如 <code>1.dwg</code>，输出目录先建好）：</p><p>Windows（cmd / PowerShell）：<code>mxcadassembly.exe {&quot;srcpath&quot;:&quot;1.dwg&quot;,&quot;outname&quot;:&quot;_trial.mxweb&quot;,&quot;outpath&quot;:&quot;./out&quot;}</code>；Windows（Git Bash）：<code>mxcadassembly.exe &quot;[%7B%22srcpath%22%3A%221.dwg%22%2C%22outname%22%3A%22_trial.mxweb%22%2C%22outpath%22%3A%22.%2Fout%22%7D]&quot;</code>；Linux：<code>./mxcadassembly &#39;{&quot;srcpath&quot;:&quot;1.dwg&quot;,&quot;outname&quot;:&quot;_trial.mxweb&quot;,&quot;outpath&quot;:&quot;./out&quot;}&#39;</code></p></blockquote><ul><li>返回 <code>{&quot;code&quot;:0,&quot;message&quot;:&quot;ok&quot;}</code> → 有效可用，直接使用。</li><li>返回非 0 → 读 <code>%TEMP%\\MxNode\\mxcad_*.log</code> 中的版本串（每次运行都会记录，格式实测样本：<code>MxCAD TryVersion:7.0(2026-10-21 11:16)(64bit)(cooperate)</code>）： <ul><li><strong>括号内日期（如 <code>2026-10-21</code>）= 试用起始日</strong>；<code>当前日期 − 试用起始日 &gt; 5 个月</code> → 过期，重新下载 zip 解压覆盖临时路径（地址见入口指引&quot;链接清单&quot;）</li><li>未过期 → 程序环境异常，按日志排错</li></ul></li></ul><p>常用 JSON 参数（详见官方《图纸转换详细说明》）：</p><ul><li>转换：<code>{&quot;srcpath&quot;:&quot;a.dwg&quot;,&quot;outname&quot;:&quot;a.mxweb&quot;,&quot;outpath&quot;:&quot;./out&quot;}</code>（路径相对转换程序目录；outname 后缀决定目标格式；mxweb 转 dwg 必须显式带 .dwg/.dxf；<code>outpath</code> 目录必须预先存在）</li><li>裁剪 DWG：<code>{&quot;cmd&quot;:&quot;cut_dwg&quot;,&quot;bd_pt1_x&quot;:0,&quot;bd_pt1_y&quot;:0,&quot;bd_pt2_x&quot;:100,&quot;bd_pt2_y&quot;:100,&quot;srcpath&quot;:&quot;a.dwg&quot;,&quot;outname&quot;:&quot;cut.dwg&quot;}</code></li><li>输出 PDF：<code>{&quot;srcpath&quot;:&quot;a.dwg&quot;,&quot;outname&quot;:&quot;a.pdf&quot;,&quot;outpath&quot;:&quot;./out&quot;,&quot;ret_page_extents&quot;:true,&quot;width&quot;:&quot;2000&quot;,&quot;height&quot;:&quot;2000&quot;,&quot;colorPolicy&quot;:&quot;mono&quot;}</code>——<strong>不带 <code>cmd</code> 字段</strong>（带则返回 <code>{&quot;code&quot;:201}</code>）；输出位置与其他转换规则一致：输出目录为 <code>outpath</code>（省略时回退转换程序目录），文件名为 <code>outname</code>（<code>outname</code> 为绝对路径时直接写该位置）</li><li><code>srcpath</code>/<code>outpath</code>/<code>outname</code> 均支持绝对路径（含中文路径）</li><li>⚠️ <strong>正式任务的产物必须写到用户要求的位置</strong>（用绝对路径或用户工作区相对路径），不要留在转换程序目录的 <code>out\\</code> 里：临时路径会被清空（重新下载前 / 系统清理），留在里面的产物（mxweb / pdf / 图片）会直接丢失；<code>./out</code> 仅用于试用检测</li><li>⚠️ <code>cmd</code> 参数域（如 <code>print_to_pdf</code> 等）属于 MxServiceCode 后端服务接口，mxcadassembly.exe 直调仅上述参数有效</li><li>若 mxcadassembly 是<strong>用户功能的运行时依赖</strong>（如&quot;上传图纸在线打开&quot;功能），注意临时路径不稳定问题（换包清空 / OS 自动清理），处理方式见《前端 mxcad 指南》1.1 节末尾&quot;运行时转换功能&quot;说明</li></ul><h2 id="四、二开工作流" tabindex="-1">四、二开工作流 <a class="header-anchor" href="#四、二开工作流" aria-label="Permalink to &quot;四、二开工作流&quot;">​</a></h2><ol><li>修改 <code>src/sample/*.ts</code> 或新增文件（API 见《Mx2DNode二开API参考.md》）</li><li>在 <code>src/MxCommand.ts</code> 注册命令（见《MxServiceCode命令参考.md》第六节）</li><li>编译：<code>npm run build</code>（node_modules 已内置；如缺失用 <code>bin\\node.exe node_modules\\typescript\\bin\\tsc --build</code>）</li><li>用 <code>bin\\node.exe mxapp.js &lt;命令&gt; 参数=值 debug=1</code> 验证</li></ol><h2 id="五、日志" tabindex="-1">五、日志 <a class="header-anchor" href="#五、日志" aria-label="Permalink to &quot;五、日志&quot;">​</a></h2><ul><li>路径：<code>%TEMP%\\MxNode</code>（Linux 同规则）</li><li>每次命令结束输出 <code>logs end</code>；<code>debug=1</code> 时日志更详细</li><li>异常返回 <code>{&quot;code&quot;:-4,&quot;message&quot;:&quot;js程序异常，详细见日志&quot;}</code> 时查日志文件</li></ul><h2 id="六、附带资源说明" tabindex="-1">六、附带资源说明 <a class="header-anchor" href="#六、附带资源说明" aria-label="Permalink to &quot;六、附带资源说明&quot;">​</a></h2><table><thead><tr><th>文件</th><th>用途</th></tr></thead><tbody><tr><td><code>empty_template.dwg</code></td><td>空白模板，<code>Mx2DDraw.getEmptyTemplateDwgFilePath()</code> 指向它</td></tr><tr><td><code>A3.dwg</code> / <code>BT.DWG</code></td><td>图框 / 图签示例（BT 块含属性定义），testParamDrawTk 使用</td></tr><tr><td><code>t1.dwg</code> / <code>tree.dwg</code></td><td>测试图纸 / 图块（tree 图块用于 testParamDraw）</td></tr><tr><td><code>mxcad_ini.json</code>（转换程序目录下）</td><td>转换程序配置（字体路径等），勿随意修改</td></tr><tr><td><code>fonts\\</code></td><td>字体目录（DWG 中 SHX/TTF 字体依赖）</td></tr></tbody></table>`,45)])])}const m=s(i,[["render",n]]);export{h as __pageData,m as default};
